const findRoadmapItem = (items: RoadmapItem[], id: string): RoadmapItem | undefined => {
  for (const item of items) {
    if (item.id === id) return item;
    const child = findRoadmapItem(item.children ?? [], id);
    if (child) return child;
  }
  return undefined;
};

const markRoadmapItems = (ids: string[], status: RoadmapItem["status"]) => {
  for (const id of ids) {
    const item = findRoadmapItem(ROADMAP_ITEMS, id);
    if (!item) throw new Error(`Roadmap reconciliation refers to unknown item ${id}`);
    item.status = status;
  }
};

